/*
 * Memory ownership and lifetimes
 * ==============================
 * Everything this library returns is allocated by Rust. Release it ONLY with
 * the matching seiza_*_free function below -- never with free(), delete,
 * CoTaskMemFree, Marshal.FreeHGlobal, or any other allocator. Mixing allocators
 * is undefined behavior. Every free function accepts NULL and no-ops, so it is
 * always safe to call.
 *
 * OWNED by the caller (you must release it):
 *   - SeizaRenderedImage* returned by the seiza_rendered_image_open* functions
 *     or seiza_live_stacker_render_preview
 *       -> release with seiza_rendered_image_free().
 *   - SeizaRenderedImage16* returned by the seiza_rendered_image16_open*
 *     functions -> release with seiza_rendered_image16_free().
 *   - SeizaBackgroundModel* returned by seiza_background_fit
 *       -> release with seiza_background_model_free().
 *   - SeizaLiveStacker* returned by seiza_live_stacker_create / _open_fits /
 *     _open_context
 *       -> release with seiza_live_stacker_free(), or consume with
 *          seiza_live_stacker_finish().
 *   - SeizaCancelSignal* returned by seiza_cancel_signal_create
 *       -> release with seiza_cancel_signal_free() after all borrowing work
 *          has returned.
 *   - SeizaStackSnapshot* returned by seiza_live_stacker_snapshot / _finish
 *       -> release with seiza_stack_snapshot_free().
 *   - SeizaStackExportSnapshot* returned by
 *     seiza_live_stacker_export_snapshot
 *       -> release with seiza_stack_export_snapshot_free().
 *   - SeizaParallax* returned by seiza_parallax_prepare_json or
 *     seiza_parallax_reconfigure_json
 *       -> release with seiza_parallax_free() once no call using it runs.
 *          Videos reconfigured from one preparation share its scene, which
 *          lives until the last of them is freed; free them in any order.
 *   - SeizaSatelliteCatalog* returned by the seiza_satellite_catalog_open,
 *     _from_omm_json, _from_tle_text, _fetch_celestrak and _resolve_json
 *     functions -> release with seiza_satellite_catalog_free() once no call
 *     using it runs.
 *   - char* returned by seiza_catalog_status_json, seiza_solve_image_json,
 *     seiza_solve_image_with_limits_json,
 *     seiza_probe_frame_json, seiza_calibration_plan_json,
 *     seiza_calibration_build_master_json, seiza_live_stacker_state_json, and
 *     seiza_live_stacker_push_*_json, seiza_parallax_summary_json,
 *     seiza_parallax_plan_tour_json, seiza_parallax_plan_scene_tour_json,
 *     seiza_satellite_catalog_info_json, seiza_satellite_catalog_tracks_json,
 *     plus
 *     any
 *     char* stored into an
 *     `error_out` argument on failure
 *       -> release with seiza_string_free().
 *
 * BORROWED by the caller (do NOT free; valid only while the owner is alive):
 *   - const uint8_t* from seiza_rendered_image_rgba / _bgra and const char*
 *     from seiza_rendered_image_metadata_json point INTO the SeizaRenderedImage
 *     and dangle the moment it is freed. Copy them out before freeing the image
 *     if you need them to outlive it.
 *   - const uint16_t* from seiza_rendered_image16_rgba and const char* from
 *     seiza_rendered_image16_metadata_json point INTO the SeizaRenderedImage16
 *     and dangle the moment it is freed.
 *   - const char* from seiza_background_model_diagnostics_json points INTO the
 *     SeizaBackgroundModel and dangles when the model is freed.
 *   - const float* / uint32_t* from seiza_live_stacker_* point INTO live stack
 *     state and remain valid only until its next mutable call, finish, or free.
 *   - const float* / uint32_t* from seiza_stack_snapshot_* point INTO the
 *     immutable SeizaStackSnapshot and dangle when the snapshot is freed.
 *   - const char* from seiza_core_version, seiza_stacking_output_version and
 *     seiza_stretch_output_version is static and is never freed.
 *   - the `json` argument to a SeizaCatalogSetupProgressCallback is valid only
 *     for the duration of that one callback; copy it if you need it afterward.
 *   - the pixels a SeizaParallaxFrameCallback receives, and the JSON a
 *     SeizaParallaxEventCallback receives, are valid only for that one call.
 *
 * Convention: a non-const `char*` return transfers ownership (free it); a
 * `const` return is borrowed (do not free).
 *
 * Errors: functions taking `char** error_out` set *error_out to NULL on success
 * and to an OWNED message on failure (and return NULL / false). Free that
 * message with seiza_string_free().
 *
 * Threading: externally synchronize each live stacker and do not mutate,
 * finish, or free it while another thread reads a borrowed live view. Do not
 * free any opaque owner while another thread uses it or its borrowed pointers.
 * A SeizaStackExportSnapshot is independent of its live stacker and may be
 * transferred to an output worker after capture; do not free it until every
 * write using it has returned.
 * seiza_cancel_signal_cancel is the exception: it is thread-safe and is meant
 * to be called while a worker borrows the signal, but the owner still must not
 * be freed until that worker returns.
 * Do not free the same pointer twice or use a pointer after its owner is freed.
 */

/*
 Additive background subtraction mode for
 [`seiza_background_model_correct_in_place`].
 */
#define SEIZA_BACKGROUND_CORRECTION_SUBTRACT 0

/*
 Multiplicative background division mode for
 [`seiza_background_model_correct_in_place`].
 */
#define SEIZA_BACKGROUND_CORRECTION_DIVIDE 1

/*
 The most channels a measurement reports separately: mono or debayered RGB.
 */
#define SEIZA_SNR_MAX_CHANNELS 3

/*
 Which numeric fields of a [`SeizaFrameSignature`] were actually recorded.

 A cleared bit means "not recorded", which is not the same as zero: a camera
 really can be set to gain 0, and a frame that does not say what gain it used
 is a different thing from one that says zero.

 The flags exist so that a zeroed struct — `= {0}`, `calloc`, `memset`, all
 of them ordinary C — means "nothing recorded" rather than "every setting is
 zero". Getting that backwards silently inverts every comparison, so the
 safe reading is the one you get for free.
 */
#define SEIZA_FRAME_HAS_WIDTH (1 << 0)

#define SEIZA_FRAME_HAS_HEIGHT (1 << 1)

#define SEIZA_FRAME_HAS_CHANNELS (1 << 2)

#define SEIZA_FRAME_HAS_BINNING_X (1 << 3)

#define SEIZA_FRAME_HAS_BINNING_Y (1 << 4)

#define SEIZA_FRAME_HAS_GAIN (1 << 5)

#define SEIZA_FRAME_HAS_OFFSET (1 << 6)

#define SEIZA_FRAME_HAS_READOUT_MODE (1 << 7)

#define SEIZA_FRAME_HAS_FOCAL_LENGTH (1 << 8)

#define SEIZA_FRAME_HAS_ROTATION (1 << 9)

#define SEIZA_FRAME_HAS_EXPOSURE (1 << 10)

#define SEIZA_FRAME_HAS_CAMERA_TEMP (1 << 11)

#define SEIZA_FRAME_HAS_CAPTURED_AT (1 << 12)

/*
 Which fields of a [`SeizaMatchTolerances`] the caller set. A cleared bit
 takes the built-in default for that tolerance.

 A zero tolerance is a legitimate ask — "these must be exactly equal" — so
 it cannot double as "unset". The flags keep both expressible, and make a
 zeroed struct mean "every default", which is what a caller who zeroes one
 almost certainly wants.
 */
#define SEIZA_TOLERANCE_HAS_EXPOSURE (1 << 0)

#define SEIZA_TOLERANCE_HAS_DARK_TEMPERATURE (1 << 1)

#define SEIZA_TOLERANCE_HAS_MASTER_TEMPERATURE (1 << 2)

#define SEIZA_TOLERANCE_HAS_ROTATION (1 << 3)

#define SEIZA_TOLERANCE_HAS_FOCAL_LENGTH (1 << 4)

#define SEIZA_TOLERANCE_HAS_FLAT_SESSION (1 << 5)

#define SEIZA_TOLERANCE_HAS_EXPOSURE_FRACTION (1 << 6)

/*
 Opt in to gain/offset differences between lights and dark-calibrated
 flats. This bit is the value, not a presence flag; clear means strict.
 Dark/light and flat/dark-flat comparisons remain strict.
 */
#define SEIZA_TOLERANCE_ALLOW_FLAT_GAIN_OFFSET_MISMATCH (1 << 7)

/*
 The light's recorded rotator angle is compared, as for any frame.
 */
#define SEIZA_LIGHT_ROTATION_RECORDED 0

/*
 An angle the host measured is compared in place of the recorded one.
 */
#define SEIZA_LIGHT_ROTATION_MEASURED 1

/*
 The host has measured that the angle does not decide the light's flats:
 any flat angle passes.
 */
#define SEIZA_LIGHT_ROTATION_UNKNOWN 2

/*
 Frame pixels as 3 bytes each, red, green, blue.
 */
#define SEIZA_PIXEL_FORMAT_RGB8 0

/*
 Frame pixels as 4 bytes each, red, green, blue and an opaque alpha.
 */
#define SEIZA_PIXEL_FORMAT_RGBA8 1

/*
 Frame pixels as 4 bytes each, blue, green, red and an opaque alpha: the
 order of Core Video's `kCVPixelFormatType_32BGRA`, Direct2D and Media
 Foundation's RGB32.
 */
#define SEIZA_PIXEL_FORMAT_BGRA8 2

